from bisect import bisect_right
from collections import defaultdict


def point_in_time_join(events, feature_rows, ttl):
    """For each (entity, event_ts) return the latest feature value known at event_ts.

    feature_rows: iterable of (entity, feature_ts, value).
    A row qualifies if feature_ts <= event_ts and event_ts - feature_ts <= ttl.
    Ties on feature_ts: the row that appears later in feature_rows wins.
    Returns a list aligned with events; None when nothing qualifies.
    """
    by_entity = defaultdict(list)
    for i, (ent, ts, val) in enumerate(feature_rows):
        by_entity[ent].append((ts, i, val))
    times = {}
    vals = {}
    for ent, rows in by_entity.items():
        rows.sort(key=lambda r: (r[0], r[1]))
        times[ent] = [r[0] for r in rows]
        vals[ent] = [r[2] for r in rows]
    out = []
    for ent, event_ts in events:
        ts_list = times.get(ent)
        if not ts_list:
            out.append(None)
            continue
        j = bisect_right(ts_list, event_ts) - 1
        if j < 0 or event_ts - ts_list[j] > ttl:
            out.append(None)
        else:
            out.append(vals[ent][j])
    return out


def naive_latest_join(events, feature_rows):
    """Leaky join: always uses the newest feature row per entity, ignoring event time."""
    latest = {}
    for ent, ts, val in feature_rows:
        if ent not in latest or ts >= latest[ent][0]:
            latest[ent] = (ts, val)
    return [latest[ent][1] if ent in latest else None for ent, _ in events]
```

Check on the example data: rows u1 at t=100 (value 2), t=200 (5 then 6), t=400 (9), u2 at t=150 (value 1), TTL 300. Events u1@99 gives None, u1@100 gives 2, u1@250 gives 6, u1@399 gives 6, u1@500 gives 9, u1@800 gives None because the row is 400 s old. The naive join gives 9 for every u1 event.

