from bisect import bisect_right
from collections import defaultdict


def point_in_time_join(events, feature_rows, ttl):
    """For each (entity, event_ts) return the latest feature value known at event_ts.

    feature_rows: iterable of (entity, feature_ts, value).
    A row qualifies if feature_ts <= event_ts and event_ts - feature_ts <= ttl.
    Ties on feature_ts: the row that appears later in feature_rows wins.
    Returns a list aligned with events; None when nothing qualifies.
    """
    by_entity = defaultdict(list)
    for i, (ent, ts, val) in enumerate(feature_rows):
        by_entity[ent].append((ts, i, val))
    times = {}
    vals = {}
    for ent, rows in by_entity.items():
        rows.sort(key=lambda r: (r[0], r[1]))
        times[ent] = [r[0] for r in rows]
        vals[ent] = [r[2] for r in rows]
    out = []
    for ent, event_ts in events:
        ts_list = times.get(ent)
        if not ts_list:
            out.append(None)
            continue
        j = bisect_right(ts_list, event_ts) - 1
        if j < 0 or event_ts - ts_list[j] > ttl:
            out.append(None)
        else:
            out.append(vals[ent][j])
    return out


def naive_latest_join(events, feature_rows):
    """Leaky join: always uses the newest feature row per entity, ignoring event time."""
    latest = {}
    for ent, ts, val in feature_rows:
        if ent not in latest or ts >= latest[ent][0]:
            latest[ent] = (ts, val)
    return [latest[ent][1] if ent in latest else None for ent, _ in events]

from collections import Counter


def categorical_skew(train, served, linf_threshold=0.10,
                     unseen_threshold=0.01, null_gap_threshold=0.02):
    """Compare a served sample of one categorical feature with its training sample.

    None means missing. Returns a dict of statistics and a list of violations.
    linf is the largest absolute gap between category frequencies, where
    frequencies are computed over non-missing values only.
    """
    if not train or not served:
        raise ValueError("both samples must be non-empty")

    def split(values):
        present = [v for v in values if v is not None]
        return Counter(present), len(present), len(values) - len(present)

    c_tr, n_tr, miss_tr = split(train)
    c_sv, n_sv, miss_sv = split(served)
    if n_tr == 0 or n_sv == 0:
        raise ValueError("a sample has no non-missing values")

    null_tr = miss_tr / len(train)
    null_sv = miss_sv / len(served)
    gaps = {}
    for cat in set(c_tr) | set(c_sv):
        gaps[cat] = abs(c_tr[cat] / n_tr - c_sv[cat] / n_sv)
    worst_cat = min(gaps, key=lambda c: (-gaps[c], str(c)))
    linf = gaps[worst_cat]
    unseen = sum(n for cat, n in c_sv.items() if cat not in c_tr) / n_sv

    violations = []
    if abs(null_sv - null_tr) > null_gap_threshold:
        violations.append("null_rate")
    if unseen > unseen_threshold:
        violations.append("unseen_categories")
    if linf > linf_threshold:
        violations.append("linf")
    return {
        "null_rate_train": null_tr,
        "null_rate_served": null_sv,
        "linf": linf,
        "linf_category": worst_cat,
        "unseen_rate": unseen,
        "violations": violations,
    }
